    "content": "美国国务院（资料图） 总台记者当地时间8月24日获悉，美政府正准备撤销多达20万名外国人的商务和旅游签证，这些外国人曾在美国申请或目前正在寻求庇护身份。如果实施，此举将成为美国历史上规模最大的一次性签证集体撤销行动，并可能面临法律挑战。 据被曝光的美国务院文件及两名美国官员透露，除非受到法律挑战或计划有所修改，否则国务院预计将在未来几周内宣布撤销那些在2016年至2026年间签发且持有人曾寻求或正在寻求庇护的所谓B1和B2类签证。这项行动将与国土安全部协同进行。 国务院发言人汤米·皮戈特表示：“我们正与国土安全部协…"
