    "description": "新华社纽约8月24日电（记者刘亚南 徐静）美国财政部长贝森特24日下午召开新闻发布会，宣布美国当日发起对伊朗“经济孤立”的新一轮制裁措施，以进一步加大对伊施压。 据美财政部外国资产控制办公室24日发布的公告，美国从当日起把对伊朗经济制裁范围扩大到航空、数字资产、黄金、航运和技术行业等5个领域。公告称，美国还将暂停多项涉伊朗的许可，涉及部分教育活动和服务、个人汇款、体育和学术交流等。此外，约60个伊朗相关实体、个人和船只被列入制裁清单，覆…",
    "content": "新华社纽约8月24日电（记者刘亚南 徐静）美国财政部长贝森特24日下午召开新闻发布会，宣布美国当日发起对伊朗“经济孤立”的新一轮制裁措施，以进一步加大对伊施压。 据美财政部外国资产控制办公室24日发布的公告，美国从当日起把对伊朗经济制裁范围扩大到航空、数字资产、黄金、航运和技术行业等5个领域。公告称，美国还将暂停多项涉伊朗的许可，涉及部分教育活动和服务、个人汇款、体育和学术交流等。此外，约60个伊朗相关实体、个人和船只被列入制裁清单，覆盖核与导弹技术、网络行动、石油贸易等。 贝森特说，美国针对伊朗在全球的金融联系发…"
