    "content": "新华社渥太华8月24日电（记者林威）加拿大政界人士24日针对美国发出的最新关税威胁密集表态，强调加拿大不会接受不平等的双边关系，并可能采取包括经济纾困与出口限制的举措应对加美贸易战。 加拿大总理卡尼说，只有在美国改变态度并建立真正伙伴关系的前提下，加方才愿意重回谈判桌。他不接受“加拿大是美国附属”的态度，也不接受加拿大在对美关系中所处不利地位。卡尼还表示，美方的做法限制了加拿大与其他国家签署贸易协定的能力，侵犯了加拿大的“核心文化利益”。 加拿大财政部长商鹏飞表示，加政府将向受关税冲击的企业提供支持政策。加方的首要…"
