    "content": "24/08/2026 - 22:24 周一（8月24日）是美国宣称经济制裁伊朗的“诺曼底登陆日”，美国财政部长斯科特‧贝森特（Scott Bessent）在新闻发布会上宣布：扩大对伊朗的经济制裁，包括部分二级制裁。 在贝森特发表讲话之前，美国财政部发布的关于其对伊朗采取行动声明表示，受制裁的实体涉及核能、导弹、网络和石油等多个领域。制裁目标是在阿联酋、香港、中国、新加坡、瑞士和欧洲等地为伊朗船队提供影子服务的经纪公司网络。 美国财政部还强调指出，数字资产、科技、黄金、航空和航运业也可能面临二级制裁。这五个行业被认定…"
