    "content": "8月24日，联合国秘书长古特雷斯在位于纽约的联合国总部举行的记者会上讲话。新华社记者 谢锷 摄 新华社联合国8月24日电（记者尚绪谦）联合国秘书长古特雷斯24日就海上航行权利与自由举行记者见面会，敦促有关各方就化肥及相关原材料海运机制与联合国合作。 古特雷斯说，霍尔木兹海峡和红海曼德海峡的袭击与航运阻断影响能源、化肥以及其他关键商品的海上运输。俄乌冲突发生后，黑海的袭击威胁到石油、粮食和其他农产品外运的关键航路。这些危机阻塞了全球贸易大动脉、严重挤压全球粮食系统。 古特雷斯说，美伊冲突爆发后，他于3月份成立了一个霍…"
