    "description": "24/08/2026 - 20:49 美国国土安全部（DHS）周一提出新规，计划把所有受年度名额限制的H-1B工作签证申请费，提高至每件10万3265美元，且这笔费用将在提交申请时缴交，并加在现有各项H-1B费用之上。 若最终实施，这将是美国就业型移民申请费用最重大的调升之一，可能大幅提高企业聘用外国专业人才的成本。 据国土安全部周一在《联邦公报》（Federal Register）上发布的通知显示，新费用目的是协助政府收回管理合法移民…",
    "content": "24/08/2026 - 20:49 美国国土安全部（DHS）周一提出新规，计划把所有受年度名额限制的H-1B工作签证申请费，提高至每件10万3265美元，且这笔费用将在提交申请时缴交，并加在现有各项H-1B费用之上。 若最终实施，这将是美国就业型移民申请费用最重大的调升之一，可能大幅提高企业聘用外国专业人才的成本。 据国土安全部周一在《联邦公报》（Federal Register）上发布的通知显示，新费用目的是协助政府收回管理合法移民制度的成本，将用于移民申请审理、诈欺侦测、国家安全审查、移民法院工作及资讯系统现…"
