    "content": "以色列总理内塔尼亚胡（资料图） 新华社耶路撒冷8月24日消息，以色列总理内塔尼亚胡24日接受以色列第14频道电视台采访时声称，伊朗曾“试图暗杀他的一个儿子”。 内塔尼亚胡没有提供更多细节。内塔尼亚胡有两个儿子，他在采访中没有透露哪一个成为所谓暗杀目标，亦未指明所谓暗杀企图的性质和时间。 《以色列时报》报道说，即使内塔尼亚胡在今年晚些时候举行的大选中落败，以国家安全总局（辛贝特）也会为内塔尼亚胡及其家庭成员提供至少5年的安全保护。 以色列第12频道电视台报道称，过去几个月来，有关伊朗企图暗杀内塔尼亚胡儿子的信息一直受…"
