    "content": "新华社东京8月24日电（记者陈泽安 杨智翔）由日本市民团体主办的“日军毒气展”23日至28日在日本神奈川县横滨市的神奈川县民中心举办。展览旨在揭批日军战时制造毒气并在侵华战争中实施毒气战的暴行，揭露日本军国主义犯下的反人类行径。 据展览介绍，二战时期，日本在广岛县大久野岛、福冈县北九州市、千叶县习志野市等地分别生产毒气、制造毒气弹、培训从事毒气战的人员，并在中国多地实施毒气战。日本战败后，一些毒气武器被遗留在中国，给当地人民带来持续伤害。然而，日本政府既未正式道歉，也未给予赔偿。 展览通过照片和文字资料，以及邀请日…"
