    "content": "当地时间8月24日，贝森特出席新闻发布会 当地时间8月24日，美国财政部长贝森特召开新闻发布会。贝森特表示，美国总统特朗普正致电各国领导人，明确要求其停止与伊朗的往来。 美国财政部长贝森特23日晚在社交媒体上说，美国同伊朗的战事正进入“终局”，扬言要切断伊朗政权“每一条经济命脉”，直至德黑兰“孤立无援”。"
