    "content": "新华社德黑兰8月24日电（记者陈霄 沙达提）伊朗伊斯兰议会议长卡利巴夫24日晚就美国新一轮制裁威胁表示，伊朗贸易伙伴已表示“不会认真对待”美方相关言论。 卡利巴夫在社交媒体上发文说，美方清楚其相关强硬言论难以取信于人，且美国当前的经济状况也不允许其进一步收紧与其他国家的经贸关系。 他说，伊朗的贸易伙伴已通过媒体表态以及直接传递信息等方式表示，“不会认真对待”美方相关言论。 美国财政部长贝森特24日召开新闻发布会，公布针对伊朗的经济制裁措施，以进一步加大对伊朗的施压。"
