    "description": "win10 上的 docker desktop ，没有启动任何容器。但是 vmmem 会疯狂吃 cpu ，一直维持在 10%以上。 尝试关闭 Enable Scout image analysis 选项后，正常了，cpu 占用降到了 1%以下。 这很奇怪啊，我又没有开 backgroup scout SBOM indexing ， 按理说不会在后台跑的，太奇怪了",
    "content": "win10 上的 docker desktop ，没有启动任何容器。但是 vmmem 会疯狂吃 cpu ，一直维持在 10%以上。 尝试关闭 Enable Scout image analysis 选项后，正常了，cpu 占用降到了 1%以下。 这很奇怪啊，我又没有开 backgroup scout SBOM indexing ， 按理说不会在后台跑的，太奇怪了"
