    "content": "英国首相伯纳姆8月24日在基辅举行的“意愿联盟”峰会上表示，他已批准向乌克兰提供生产“风暴之影”巡航导弹所需的技术，以帮助乌克兰自行发展远程打击能力。 伯纳姆说，英国曾于2023年率先向乌克兰提供远程武器。乌克兰总统泽连斯基此次要求英国分享“风暴之影”技术，以便乌方自行发展相关能力。 所谓“意愿联盟”，是由英国、法国等欧洲国家推动建立的支持乌克兰的多国合作机制。目前已有数十个国家参与，主要任务包括协调对乌军事、财政支持，以及讨论未来停火后的安全保障。"
