    "author": "澎湃新闻记者 庄岸",
    "description": "8月24日，云南省腾冲市专项整改整治工作组就“别墅”小镇私挖违建发布情况通报： 针对媒体反映的腾冲一小区存在违建问题，腾冲市委、市政府已成立专项整改整治工作组，全面开展专项排查、安全评估、整改处置等工作，及时回应社会关切，自觉接受社会监督。 此前据《人民日报》报道，有网友在人民网“领导留言板”反映称，将几百平方米的“别墅”加建成几千平方米的民宿或豪华酒店……情况真如读者来信所说吗？记者近日来到云南腾冲市高黎贡国际健康旅居小镇走访调查。 …",
    "content": "8月24日，云南省腾冲市专项整改整治工作组就“别墅”小镇私挖违建发布情况通报： 针对媒体反映的腾冲一小区存在违建问题，腾冲市委、市政府已成立专项整改整治工作组，全面开展专项排查、安全评估、整改处置等工作，及时回应社会关切，自觉接受社会监督。 此前据《人民日报》报道，有网友在人民网“领导留言板”反映称，将几百平方米的“别墅”加建成几千平方米的民宿或豪华酒店……情况真如读者来信所说吗？记者近日来到云南腾冲市高黎贡国际健康旅居小镇走访调查。 高黎贡国际健康旅居小镇位于腾冲市腾越镇东山片区，背靠国家4A级旅游景区东山草原。…"
