    "content": "祁东金泰米业为“施救晕倒老人遭索赔”店主送上慰问金。 8月24日下午，湖南祁东金泰米业总经理龚胜利专程来到祁东县洪桥街道，走访慰问肖爱华一家，为他们送上了2万元慰问金，以实际行动鼓励凡人善举，弘扬全社会扬善崇德之风。 此前，一位老人因身体不适在肖爱华经营的店铺休息时晕倒，肖爱华主动实施救助，送医后老人不幸离世。老人家属质疑救助不当，向肖爱华索赔。 有关部门对此进行了调解，确认肖爱华没有过错，不承担法律责任。 后肖爱华出于人道主义关怀，一次性帮扶死者家属1.9万元。 慰问中，龚胜利对她的善举表示敬意。“做好事有可能引…"
