    "description": "感谢IT之家网友 風見暉一、西窗 的线索投递！ IT之家 8 月 24 日消息，据央视新闻，当地时间 8 月 24 日，法国总统马克龙表示，他已颁布有关法律，从今年秋季新学年起禁止高中生在校使用手机。 马克龙表示，保护儿童免受电子屏幕带来的负面影响已刻不容缓，“没有手机的学校意味着重新找回安宁的学习环境”。 法国议会此前于 7 月 21 日通过旨在保护未成年人免受社交网络风险影响的相关法律。法律规定，学生在小学、初中和高中校园内不得使用…",
    "content": "感谢IT之家网友 風見暉一 、 西窗 的线索投递！ IT之家 8 月 24 日消息，据央视新闻，当地时间 8 月 24 日，法国总统马克龙表示，他已颁布有关法律，从今年秋季新学年起禁止高中生在校使用手机。 马克龙表示，保护儿童免受电子屏幕带来的负面影响已刻不容缓，“没有手机的学校意味着 重新找回安宁的学习环境 ”。 法国议会此前于 7 月 21 日通过旨在 保护未成年人免受社交网络风险影响 的相关法律。法律规定，学生在小学、初中和高中校园内不得使用手机或其他电子通信终端设备。 另一方面，据IT之家此前报道，当地时间…"
