    "content": "24/08/2026 - 15:51 周一(8月24日)，伊朗货币里亚尔跌至历史新低。与此同时，美国政府准备宣布新一轮制裁，并表示这些措施将进一步加大对伊朗的压力。 周一外汇市场开盘时，里亚尔跌至1美元兑202万里亚尔，创下历史新低。伊朗央行公布的官方汇率约为1美元兑150万里亚尔，但大多数伊朗人实际支付和交易时采用的是市场汇率。 在美国和以色列于2月28日袭击伊朗之前，伊朗里亚尔就已经承受巨大压力。当时伊朗面临两位数的通胀率和经济负增长。如今，随着战争持续近半年，经济受到的冲击进一步加剧，里亚尔也一次又一次刷新历…"
