    "content": "24/08/2026 - 16:10 路透社报道称，三名消息人士周一（8月24日）表示，中国国家主席习近平可能出席下个月在新德里举行的金砖国家峰会，并率领一个规模庞大的代表团。这将是习近平七年来首次访问印度，也将是中印这两个竞争对手关系出现缓和的又一迹象。 据悉，印度将于9月12日至13日主办此次峰会。届时，习近平是否出席受到的关注，因为外界更多地关注此举将释放怎样的信号，尤其是在2020年发生致命边境冲突后，北京和新德里正努力推动双边关系趋于稳定。 去年，印度总理莫迪时隔七年首次访问中国，但两国关系只是逐步改善。…"
