    "description": "新华社北京8月24日电（记者叶昊鸣）记者24日从交通运输部获悉，今年前7个月，我国跨区域人员流动量为397.9亿人次，同比增长0.8%。其中，公路人员流动量为363.9亿人次，同比增长0.6%；水路客运量为1.5亿人次，同比增长0.6%。 货运量方面，前7个月，我国完成营业性货运量329.7亿吨，同比增长2.8%。其中，完成公路货运量249.8亿吨，同比增长2.9%；完成水路货运量49.3亿吨，同比增长3%。 港口货物吞吐量方面，前7个…",
    "content": "新华社北京8月24日电（记者叶昊鸣）记者24日从交通运输部获悉，今年前7个月，我国跨区域人员流动量为397.9亿人次，同比增长0.8%。其中，公路人员流动量为363.9亿人次，同比增长0.6%；水路客运量为1.5亿人次，同比增长0.6%。 货运量方面，前7个月，我国完成营业性货运量329.7亿吨，同比增长2.8%。其中，完成公路货运量249.8亿吨，同比增长2.9%；完成水路货运量49.3亿吨，同比增长3%。 港口货物吞吐量方面，前7个月，我国完成港口货物吞吐量105.6亿吨，同比增长1.3%，其中内、外贸吞吐量同…"
