    "content": "新华社呼和浩特8月24日电 （记者张丽娜、赵泽辉、安路蒙）欢喜梁不宽，梁顶只容得下十几双脚。沙土、沙蒿、野花，是这道梁上最常见的东西。67岁的“赛考斯”（本名罗纳德·萨科尔斯基）踩着沙土登上去，风从林海那边吹来。他身旁是殷玉珍，她笑着指了指脚下：“这叫欢喜梁。” 他跟着念了一遍，发音生涩，却认真。 8月24日，殷玉珍带“赛考斯”参观“赛考斯林”。新华社记者 连振 摄 这道梁，曾经鲜有欢喜。 1988年，殷玉珍和丈夫雇了一头母牛进沙地驮树苗。翻过这道陡梁时，沙地上拖出一道血迹——母牛半路产了小牛犊。那批树苗格外高。双…"
