    "description": "新华社莫斯科8月24日电（记者王作葵）俄罗斯总统新闻秘书佩斯科夫24日表示，英国计划向乌克兰转让巡航导弹生产技术是“火上浇油”，俄方对此给予“极其负面”的评价。 据媒体报道，法国与乌克兰计划在乌建立“斯卡普”导弹生产线。英国首相伯纳姆24日到访乌克兰，预计将向乌方转让该导弹英国部件的相关技术信息。 佩斯科夫24日在新闻发布会上说，英国一边“火上浇油”，一边阻挠和平进程。俄军正收集相关资料，以确定“斯卡普”导弹可能在乌克兰的生产地点，并将…",
    "content": "新华社莫斯科8月24日电（记者王作葵）俄罗斯总统新闻秘书佩斯科夫24日表示，英国计划向乌克兰转让巡航导弹生产技术是“火上浇油”，俄方对此给予“极其负面”的评价。 据媒体报道，法国与乌克兰计划在乌建立“斯卡普”导弹生产线。英国首相伯纳姆24日到访乌克兰，预计将向乌方转让该导弹英国部件的相关技术信息。 佩斯科夫24日在新闻发布会上说，英国一边“火上浇油”，一边阻挠和平进程。俄军正收集相关资料，以确定“斯卡普”导弹可能在乌克兰的生产地点，并将采取措施将其摧毁。 “斯卡普”导弹由法国和英国联合研发，英国称之为“风暴之影”。…"
