    "content": "新华社南宁8月24日电（记者杨驰）近日，今年第19号台风“紫檀”成了热门话题——它没有直奔陆地的利落劲儿，反倒在北部湾海面兜兜转转、原地回旋，8月24日已进入到了第四天，把强降雨持续“焊”在北部湾沿海地区。不少网民疑惑：这股台风为啥“赖”在海面不走？它还将带来哪些影响？记者就此采访气象专家，揭示台风“原地转圈”背后的气象真相。 “台风就像被气流牵着走的‘风筝’，引导气流是它前进的主要动力。”广西壮族自治区气象台首席预报员祁丽燕解释，台风“紫檀”之所以迟迟不挪窝，核心原因就是引导气流太弱。周边的天气系统“各拉各的”，…"
