    "title": "欧盟气候机构：全球日均海表温度刷新历史纪录",
    "link": "http://www.news.cn/20260824/e8f2008c828a4c83a36726eee9263599/c.html",
    "pub_date": "2026-08-24 21:25:20",
    "author": "张兆卿,张馨文",
    "description": "新华社布鲁塞尔8月24日电（记者张兆卿 张馨文）欧盟气候监测机构哥白尼气候变化服务局24日发布公报说，全球日平均海洋表面温度22日达到21.10摄氏度，超过2024年3月创下的21.09摄氏度的纪录，成为有记录以来的最高值。 公报说，全球海表温度通常在南半球夏季结束后的3月至4月达到最高水平，但此次高温纪录出现在8月，这尤其值得关注。2026年以来，南纬60度至北纬60度之间的全球海洋表面平均温度在多个月份出现创纪录或接近纪录的高温，凸…",
    "content": "新华社布鲁塞尔8月24日电（记者张兆卿 张馨文）欧盟气候监测机构哥白尼气候变化服务局24日发布公报说，全球日平均海洋表面温度22日达到21.10摄氏度，超过2024年3月创下的21.09摄氏度的纪录，成为有记录以来的最高值。 公报说，全球海表温度通常在南半球夏季结束后的3月至4月达到最高水平，但此次高温纪录出现在8月，这尤其值得关注。2026年以来，南纬60度至北纬60度之间的全球海洋表面平均温度在多个月份出现创纪录或接近纪录的高温，凸显全球大部分海域持续偏暖的态势。 欧洲中期天气预报中心气候战略负责人萨曼莎·伯吉…"
