    "content": "新华社南宁8月24日电（记者郭轶凡）8月24日下午，“平陆运河泰禾2号”旅游客船平稳靠泊广西平陆运河钦州水上综合服务区，标志着平陆运河首次客船航线测试顺利完成，为平陆运河常态化江海旅游航线开通奠定基础。 “平陆运河泰禾2号”船舶船长32米、船宽5.4米，额定载客100人。该船18日从柳州白沙码头启航一路南下，24日中午完成平陆运河青年枢纽过闸作业，下午2时30分左右安全抵达平陆运河钦州水上综合服务区，完成全程620公里的航行。 此次长距离跨区域航行，是对平陆运河保障客船通航的航行条件、船闸运行效率以及水上服务区保障…"
