    "description": "今年是我国开展东西部协作30周年。新华社记者行程3200多公里，跟踪拍摄两位当前正分别在江苏省泰州市海陵区和陕西省咸阳市长武县挂职交流的干部，跟着他们上土塬、下田地、跑项目，记录两地交流干部如何“沉浸式”深入当地，推动东西部产业互补、人员互动、技术互学、观念互通、作风互鉴，实现互利共赢、共同发展。 作者：陈思、林珑、李周华 新华社音视频部制作",
