    "author": "奚天麒",
    "description": "新华社香港8月24日电（奚天麒）锦绣中华·国际青少儿风采嘉年华暨第四届“金紫荆杯”国际青少儿风采大赛全球总决赛颁奖典礼24日在香港生产力促进局举行。来自内地多个省份、港澳台地区及海外的青少儿选手代表齐聚现场，参与人数逾150人。 香港特区立法会议员陈勇通过视频致辞表示，本次活动以“锦绣中华，相约香港”为主题，以赛事为纽带、以家乡文化为根基，全方位促进内地、港澳台及海外华人青少儿之间的交流互鉴。这既是香港发挥国际化优势的重要体现，也是承担…",
    "content": "新华社香港8月24日电（奚天麒）锦绣中华·国际青少儿风采嘉年华暨第四届“金紫荆杯”国际青少儿风采大赛全球总决赛颁奖典礼24日在香港生产力促进局举行。来自内地多个省份、港澳台地区及海外的青少儿选手代表齐聚现场，参与人数逾150人。 香港特区立法会议员陈勇通过视频致辞表示，本次活动以“锦绣中华，相约香港”为主题，以赛事为纽带、以家乡文化为根基，全方位促进内地、港澳台及海外华人青少儿之间的交流互鉴。这既是香港发挥国际化优势的重要体现，也是承担中华文化对外传播、对内传承使命的关键一步。 香港普通话专业协会主席靳彤彤在典礼上…"
