    "title": "今天的毛乌素沙地，藏着几代人不变的坚守",
    "link": "http://www.news.cn/20260824/315ca304d3164b9982771b08981ee29f/c.html",
    "pub_date": "2026-08-24 20:49:11",
    "author": "连振",
    "description": "时隔26年 “赛考斯”应邀回到 殷玉珍位于毛乌素沙地的家 重逢的故事感动了万千网友 这段跨越国籍的友谊 正是在毛乌素沙地结下的 毛乌素沙地 是我国四大沙地之一 横亘陕西、内蒙古、宁夏三地 1953年拍摄的陕西榆林鱼河堡房屋被沙压盖的情形（资料照片）。新华社记者 武纯展 摄 70多年来 人们与风沙进行着不懈的斗争 当地涌现出众多治沙英雄 这是1963年，榆林人民在毛乌素沙地南端营造起来的防护林带（资料照片）。新华社记者 和坪 摄 宁夏盐池…",
