    "content": "首店云集、首秀频频，规模效应、品牌效应聚集了人气，带火了消费。近日，新华社记者随着“活力中国调研行”采访团，走进福建省厦门市，看“首”字出圈，如何持续激发这一滨海花园城市消费活力。 图为福建厦门万象城二期商场。新华社记者 林善传 摄 今年上半年，厦门万象城二期正式投入运营。厦门万象城门店副总经理邓学介绍，商城落地城市首店、特色旗舰店超50家，首店率达43%。 近年来，厦门将发展首发经济作为建设区域性国际消费中心城市、激发消费活力的重要抓手，着力构建“政策引导、载体支撑、场景赋能、服务保障”四位一体的首发经济服务体系…"
