    "content": "新华社北京8月24日电（记者魏弘毅）水利部24日组织滚动会商，分析研判全国雨情水情汛情形势，对西北、华北地区暴雨洪水防御工作作出针对性安排部署。 据预报，受冷暖空气共同影响，8月25日至28日，西北中部东部、华北中部北部等地将有一次较强降雨过程，以中到大雨为主，其中内蒙古中南部、陕西北部、山西北部、河北中部、天津等地部分地区将有暴雨到大暴雨；黄河上中游干流及支流湟水、大黑河、皇甫川、窟野河，海河流域永定河、大清河、滹沱河等河流将出现涨水过程，暴雨区内部分中小河流可能发生超警以上洪水，山丘区山洪灾害风险较高。 为应对…"
