    "description": "受今年第19号台风“紫檀”影响，广西崇左宁明县出现持续强风雨天气。明江宁明大桥段水位持续上涨，基本与桥面持平。上游冲刷下来的树枝、杂草等漂浮物持续冲击桥面，当地救援力量正动用机械开展清理作业。洪峰将于25日晚间抵达宁明县城，预计水位将漫过桥面，大桥安全面临考验。 作者：梁舜、孙闯、陈一帆、姜涛 新华社音视频部制作",
