    "content": "8月24日上午，国务院总理李强在北京人民大会堂会见来华进行国事访问的约旦国王阿卜杜拉二世。新华社记者 黄敬文 摄 新华社北京8月24日电 8月24日上午，国务院总理李强在北京人民大会堂会见来华进行国事访问的约旦国王阿卜杜拉二世。 李强表示，近年来，在两国元首战略引领下，中约关系保持健康稳定发展，务实合作成果丰硕。习近平主席将同国王陛下举行会谈，共同擘画中约关系发展新蓝图。明年中约将迎来建交50周年，中方愿同约方一道弘扬传统友好，增进政治互信，在涉及彼此核心利益问题上坚定相互支持，不断深化互利合作，在实现现代化的道路…"
