    "content": "新华社香港8月24日电（记者刘媛媛）香港特区政府发展局24日公布，位于北部都会区（北都）洪水桥／厦村新发展区内的片区（洪水桥片区）项目完成评标并经特区政府中央投标委员会批准，特区政府决定将项目批予洪水桥新发展有限公司。 中标公司的六个股东分别为中国海外发展有限公司、招商局置地有限公司、华润置地有限公司、中国旅游集团有限公司、京东集团股份有限公司及信和置业有限公司的子公司。发展局表示，中标公司在非价格和价格方面的评分均比另一家投标公司得分高，中标价为10.3亿港元。 发展局表示，中标公司将负责平整及发展三幅住宅用地，…"
