    "description": "近期，国际金价快速反弹。上周，国际现货黄金连续突破4400美元、4500美元和4600美元三道整数关口，周涨幅超过5%。伴随金价走强，A股黄金相关ETF也集体上涨，部分黄金股ETF单日涨幅超过4%。数据显示，截至8月23日，13只黄金和黄金股相关ETF最新规模超过2700亿元，近一个月规模增长超过380亿元。 (央视财经)",
