    "title": "零跑汽车确认布局机器人业务，称将很快发布正式公告",
    "link": "https://36kr.com/newsflashes/3953509263703432?f=rss",
    "pub_date": "2026-08-24 20:37:35",
    "author": "",
    "description": "8月24日，在零跑汽车2026年中期业绩电话会上，公司副总裁李腾飞回应机器人业务传闻称，新能源汽车企业、尤其是具备全域自研能力的新能源汽车企业，是最具备条件做机器人的企业之一，零跑确实在这方面有我们自己的规划，具体信息将很快通过正式公告发布。此前工商信息显示，零跑旗下浙江凌昇动力科技有限公司于2026年7月全资设立湖州凌昇精密制造有限公司，注册资本2.1亿元，经营范围包含工业机器人制造、智能机器人研发。（界面）",
